@gene('Z59a', 'cache goal field, own field value, health, enemy tiles and nearby-enemy count once per turn', parents=['s4'])
def update() -> None:
    GF = goal_field()
    EN = enemy_tiles()
    HERE = at(GF, me().pos)
    HF = me().health_frac
    NEAR_EN = count(dist(e, me().pos) <= 4 for e in EN)

@gene('s4', 'progress toward goals (cached field, cached enemy tiles); discounted by enemies near the target, more when hurt')
def progress(t: Tile) -> Num:
    p = HERE - at(GF, t)
    if NEAR_EN == 0 and HF >= 0.5:
        return p
    danger = count(dist(e, t) <= 3 for e in EN)
    if danger > 0:
        if HF < 0.5:
            p -= 2 * danger
        elif NEAR_EN > 2:
            p -= 1
    return p
```

This mutation changes `goals()` so that cleared groups waiting for capture come first, then living groups that hold gems or gold. Otherwise it falls back to the original "all living groups" behaviour. The gem-carrying altar branch is unchanged. I have not run this in the arena, so the fuel cost and win effect are untested.

```python
@gene("s2b", "goals: altar when carrying; else cleared groups awaiting capture, then valued living groups", parents=["s2"])
def goals() -> Tiles:
    if gems() > 0:
        acc = near(tile(-5, -5), 0)
        for a in altars() - locked_altars():
            acc = acc | near(a, 0.5607)
        return acc
    acc = near(tile(-5, -5), 0)
    for g in range(num_groups()):
        if group_reward(g):
            acc = acc | group_tiles(g)
    if size(acc) > 0:
        return acc
    for g in range(num_groups()):
        if not group_respawning(g) and group_gems(g) + group_gold(g) > 0:
            acc = acc | group_tiles(g)
    if size(acc) > 0:
        return acc
    for g in range(num_groups()):
        if not group_respawning(g):
            acc = acc | group_tiles(g)
    return acc
```

